// ============================================================
// KNIGHT — script.js
// Talks to OUR OWN server (server.js + database.js) via fetch()
// and Socket.IO — Supabase has been fully removed. Every call
// below hits a real endpoint; failures show real error text,
// there is no fake local-only fallback dashboard.
// ============================================================

const API = ''; // same-origin — server.js serves this file itself
let authToken = localStorage.getItem('knight_token') || null;
let socket = null;

function authHeaders() {
  return authToken ? { 'Authorization': `Bearer ${authToken}` } : {};
}
async function api(path, { method = 'GET', body } = {}) {
  const res = await fetch(API + path, {
    method,
    headers: { 'Content-Type': 'application/json', ...authHeaders() },
    body: body ? JSON.stringify(body) : undefined
  });
  const data = await res.json().catch(() => ({}));
  if (!res.ok) throw new Error(data.error || `Request failed (${res.status})`);
  return data;
}

const DEFAULT_STATE = {
  userId: null, socialId: null, username: "", email: "", role: "Coder",
  bio: "", github: "", twitter: "", device: "Windows", level: 1,
  stats: { followers: 0, projects: 0, commits: 0 },
  avatarImgSrc: null, notifications: [], friendRequests: []
};
let userState = { ...DEFAULT_STATE };

// ---------- AVATARS (grouped: skeletons / scenery / logos) ----------
function generateFeaturedAvatars(gridId, onSelect) {
  const grid = document.getElementById(gridId);
  if (!grid) return;
  grid.innerHTML = '';
  KNIGHT_AVATAR_GROUPS.forEach(group => {
    const label = document.createElement('div');
    label.style.cssText = 'flex-basis:100%; font-size:.68rem; text-transform:uppercase; letter-spacing:.05em; color:var(--text-tertiary); margin-top:8px;';
    label.textContent = group.label;
    grid.appendChild(label);
    group.items.forEach((src, i) => {
      const div = document.createElement('div');
      div.className = 'avatar-item';
      div.innerHTML = `<img src="${src}" alt="${group.label} ${i}">`;
      div.onclick = () => {
        grid.querySelectorAll('.avatar-item').forEach(el => el.classList.remove('active'));
        div.classList.add('active');
        onSelect(src);
      };
      grid.appendChild(div);
    });
  });
}
function renderAvatarElement(container) {
  if (!container) return;
  container.innerHTML = userState.avatarImgSrc
    ? `<img src="${userState.avatarImgSrc}" style="width:100%;height:100%;object-fit:cover;">`
    : `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="width:60%;height:60%;color:var(--text-tertiary);"><path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="12" cy="7" r="4"/></svg>`;
}

// ============================================================
// DEVICE OPTIMIZATION ENGINE (unchanged — website-only shortcuts)
// ============================================================
function detectLikelyDevice() {
  const ua = navigator.userAgent;
  if (/Macintosh/.test(ua) && navigator.maxTouchPoints <= 1) return "MacBook";
  if (/Windows/.test(ua)) return "Windows";
  if (/iPad|Tablet/.test(ua)) return "Tablet";
  if (/iPhone|Android.*Mobile/.test(ua)) return "Smartphone";
  return "Windows";
}
function applyDeviceCSS(deviceName) {
  document.body.classList.remove('device-windows','device-macbook','device-smartphone','device-tablet','device-console','device-handheld','device-headphones');
  document.body.classList.add('device-' + deviceName.toLowerCase());
  document.querySelectorAll('#deviceSelectionGrid .device-card').forEach(card => {
    card.classList.toggle('selected', card.getAttribute('data-device') === deviceName);
  });
  const badge = document.getElementById('headerDeviceName');
  if (badge) badge.textContent = deviceName;
}
function selectDevice(deviceName) {
  userState.device = deviceName;
  localStorage.setItem('knight_device', deviceName);
  applyDeviceCSS(deviceName);
  showToast(`Optimized for ${deviceName}`);
  closeModal('deviceModal');
  if (userState.userId) api('/api/profile/me', { method: 'PUT', body: { device: deviceName } }).catch(() => {});
}

window.addEventListener('keydown', (e) => {
  const toolMap = { '1':'terminalPage','2':'projectsPage','3':'studioPage','4':'commPage','5':'arcadePage' };
  if (e.key === 'Escape') { closeAllModals(); closeActiveKnightPage(); }
  if (e.key === '?' && document.activeElement.tagName !== 'INPUT' && document.activeElement.tagName !== 'TEXTAREA') {
    e.preventDefault(); openKnightPage('shortcutPage'); showToast('? → Knight Shortcuts');
  }
  const modifierHeld = userState.device === 'MacBook' ? e.metaKey : e.altKey;
  const modLabel = userState.device === 'MacBook' ? '⌘' : 'Alt+';
  if (modifierHeld && toolMap[e.key]) { e.preventDefault(); openKnightPage(toolMap[e.key]); showToast(`${modLabel}${e.key}`); }
  if (modifierHeld && e.key.toLowerCase() === 'p') { e.preventDefault(); openModal('profileModal'); showToast(`${modLabel}P → Profile`); }
  if (modifierHeld && e.key.toLowerCase() === 'n') { e.preventDefault(); openModal('notificationsModal'); showToast(`${modLabel}N → Notifications`); }
  if (modifierHeld && e.key.toLowerCase() === 'd') { e.preventDefault(); openModal('deviceModal'); showToast(`${modLabel}D → Device Optimization`); }

  if (userState.device === 'Headphones') {
    const mediaKeys = ['MediaTrackNext','MediaTrackPrevious','MediaPlayPause'];
    if (mediaKeys.includes(e.key)) {
      e.preventDefault();
      const focusables = Array.from(document.querySelectorAll('button,[href],input,select,textarea,[tabindex]:not([tabindex="-1"]),.dash-card,.notif-item,.device-card,.os-tab')).filter(el => el.offsetParent !== null);
      const idx = focusables.indexOf(document.activeElement);
      if (e.key === 'MediaTrackNext') focusables[(idx+1+focusables.length)%focusables.length]?.focus();
      else if (e.key === 'MediaTrackPrevious') focusables[(idx-1+focusables.length)%focusables.length]?.focus();
      else if (e.key === 'MediaPlayPause') { document.activeElement?.click(); showToast('Activated via Play/Pause'); }
    }
  }
});
function wireHandheldControls() {
  document.getElementById('btnA')?.addEventListener('click', () => { document.activeElement?.click(); showToast('A: Activated'); });
  document.getElementById('btnB')?.addEventListener('click', () => { closeAllModals(); showToast('B: Closed'); });
}
function wireConsoleDpad() {
  const step = (dir) => {
    const focusables = Array.from(document.querySelectorAll('button,[href],input,select,textarea,[tabindex]:not([tabindex="-1"]),.dash-card')).filter(el => el.offsetParent !== null);
    const idx = focusables.indexOf(document.activeElement);
    let next = dir === 'next' ? (idx+1+focusables.length)%focusables.length : (idx-1+focusables.length)%focusables.length;
    focusables[next]?.focus();
  };
  document.getElementById('dpadRight')?.addEventListener('click', () => step('next'));
  document.getElementById('dpadDown')?.addEventListener('click', () => step('next'));
  document.getElementById('dpadLeft')?.addEventListener('click', () => step('prev'));
  document.getElementById('dpadUp')?.addEventListener('click', () => step('prev'));
  document.getElementById('dpadCenter')?.addEventListener('click', () => document.activeElement?.click());
}
function closeAllModals() { document.querySelectorAll('.modal-overlay.active').forEach(m => m.classList.remove('active')); }

function getActiveKnightPageId() {
  return document.querySelector('.knight-page.active')?.id || null;
}
function openKnightPage(id) {
  if (!document.getElementById(id)) return;
  closeAllModals(); // a full-screen page should never be hidden behind a leftover modal
  document.querySelectorAll('.knight-page.active').forEach(p => p.classList.remove('active'));
  document.getElementById(id).classList.add('active');
  window.scrollTo({ top: 0 });
  if (window.location.hash !== '#' + id) history.pushState({ page: id }, '', '#' + id);
}
function closeKnightPage(id) {
  document.getElementById(id)?.classList.remove('active');
  if (window.location.hash) history.pushState({}, '', window.location.pathname + window.location.search);
}
function closeActiveKnightPage() {
  const activeId = getActiveKnightPageId();
  if (activeId) closeKnightPage(activeId);
}
window.addEventListener('popstate', (e) => {
  document.querySelectorAll('.knight-page.active').forEach(p => p.classList.remove('active'));
  closeAllModals();
  if (e.state?.page && document.getElementById(e.state.page)) {
    document.getElementById(e.state.page).classList.add('active');
  }
});

// ============================================================
// KNIGHT SHORTCUTS — real, website-only shortcuts (not OS shortcuts)
// ============================================================
const WINDOWS_SHORTCUTS = [
  ["Alt + 1", "Open Terminal"], ["Alt + 2", "Open Projects Manager"], ["Alt + 3", "Open Studio"],
  ["Alt + 4", "Open Communication"], ["Alt + 5", "Open Arcade / Game Booster"],
  ["Alt + P", "Open your Profile"], ["Alt + N", "Open Notifications"], ["Alt + D", "Open Device Optimization settings"],
  ["Esc", "Close any open modal or panel"], ["?", "Open this Knight Shortcuts page"],
  ["Tab", "Move focus to the next control on the page"], ["Enter / Space", "Activate the focused button or card"],
];
const MACOS_SHORTCUTS = [
  ["⌘ + 1", "Open Terminal"], ["⌘ + 2", "Open Projects Manager"], ["⌘ + 3", "Open Studio"],
  ["⌘ + 4", "Open Communication"], ["⌘ + 5", "Open Arcade / Game Booster"],
  ["⌘ + P", "Open your Profile"], ["⌘ + N", "Open Notifications"], ["⌘ + D", "Open Device Optimization settings"],
  ["Esc", "Close any open modal or panel"], ["?", "Open this Knight Shortcuts page"],
  ["Tab", "Move focus to the next control on the page"], ["Enter / Space", "Activate the focused button or card"],
];
function renderShortcutList(os, filter = "") {
  const grid = document.getElementById('shortcutGrid');
  if (!grid) return;
  const data = os === 'windows' ? WINDOWS_SHORTCUTS : MACOS_SHORTCUTS;
  const f = filter.trim().toLowerCase();
  grid.innerHTML = '';
  data.filter(([k,d]) => !f || k.toLowerCase().includes(f) || d.toLowerCase().includes(f))
      .forEach(([k,d]) => {
        const card = document.createElement('div');
        card.className = 'shortcut-card';
        card.innerHTML = `<span class="shortcut-desc">${d}</span><span class="shortcut-keys">${k}</span>`;
        grid.appendChild(card);
      });
  const countEl = document.getElementById('shortcutCount');
  if (countEl) countEl.textContent = `${data.length} shortcuts (${os === 'windows' ? 'Windows keys' : 'Mac keys'})`;
}
function initShortcutPage() {
  document.querySelectorAll('.os-tab').forEach(tab => {
    tab.addEventListener('click', () => {
      document.querySelectorAll('.os-tab').forEach(t => t.classList.remove('active'));
      tab.classList.add('active');
      renderShortcutList(tab.dataset.os, document.getElementById('shortcutSearchInput')?.value || "");
    });
  });
  document.getElementById('shortcutSearchInput')?.addEventListener('input', (e) => {
    const activeOs = document.querySelector('.os-tab.active')?.dataset.os || 'windows';
    renderShortcutList(activeOs, e.target.value);
  });
  renderShortcutList('windows');
}

// ============================================================
// UI HELPERS
// ============================================================
function showToast(message) {
  const toast = document.getElementById('toast');
  if (!toast) return;
  document.getElementById('toastMsg').textContent = message;
  toast.style.bottom = '32px';
  clearTimeout(toast._t);
  toast._t = setTimeout(() => { toast.style.bottom = '-100px'; }, 3000);
}
function openModal(id) {
  if (id === 'editProfileModal') populateEditModal();
  if (id === 'profileModal') refreshIncomingRequests();
  document.getElementById(id)?.classList.add('active');
}
function closeModal(id) { document.getElementById(id)?.classList.remove('active'); }
window.addEventListener('click', (e) => { if (e.target.classList.contains('modal-overlay')) e.target.classList.remove('active'); });

function renderUI() {
  document.getElementById('dashUsernameText').textContent = userState.username;
  renderAvatarElement(document.getElementById('dashUserAvatar'));
  renderAvatarElement(document.getElementById('modalAvatar'));
  renderAvatarElement(document.getElementById('editAvatarPreviewWrap'));

  document.getElementById('modalUsername').textContent = userState.username;
  document.getElementById('modalRoleBadge').textContent = userState.role;
  document.getElementById('userLevelVal').textContent = userState.level;
  document.getElementById('modalBio').textContent = userState.bio || "No bio provided.";
  document.getElementById('socialIdChip').textContent = userState.socialId || 'KNT-------';
  document.getElementById('headerSocialIdChip').textContent = userState.socialId || 'KNT-------';

  const linksList = document.getElementById('modalLinksList');
  linksList.innerHTML = '';
  if (userState.github) linksList.innerHTML += `<a href="${userState.github}" target="_blank" class="profile-link-tag">GitHub</a>`;
  if (userState.twitter) linksList.innerHTML += `<a href="https://twitter.com/${userState.twitter.replace('@','')}" target="_blank" class="profile-link-tag">${userState.twitter}</a>`;

  document.getElementById('statFollowers').textContent = userState.stats.followers.toLocaleString();
  document.getElementById('statProjects').textContent = userState.stats.projects.toLocaleString();
  document.getElementById('statCommits').textContent = userState.stats.commits.toLocaleString();

  document.getElementById('headerDeviceName').textContent = userState.device;
  applyDeviceCSS(userState.device);

  const unread = userState.notifications.filter(n => n.unread).length + userState.friendRequests.length;
  document.getElementById('notifBadge').classList.toggle('hidden', unread === 0);
  renderNotifications();
}
function renderNotifications() {
  const container = document.getElementById('notificationsContainer');
  container.innerHTML = '';
  userState.friendRequests.forEach(r => {
    const div = document.createElement('div');
    div.className = 'notif-item gold unread';
    div.innerHTML = `<div><div class="notif-title">Friend request</div><div class="notif-desc">${r.fromProfile?.username || 'Someone'} wants to connect</div></div>
      <div style="display:flex; gap:6px;"><button class="nav-cta" style="padding:4px 10px;font-size:.7rem;" onclick="acceptFriendRequestUI('${r.id}')">Accept</button></div>`;
    container.appendChild(div);
  });
  if (userState.notifications.length === 0 && userState.friendRequests.length === 0) {
    container.innerHTML += `<p style="text-align:center; color:var(--text-tertiary); font-size:0.85rem; padding:20px;">No alerts present.</p>`;
    return;
  }
  userState.notifications.forEach(n => {
    const div = document.createElement('div');
    div.className = `notif-item ${n.type} ${n.unread ? 'unread' : ''}`;
    div.onclick = () => { n.unread = false; renderUI(); };
    div.innerHTML = `<div><div class="notif-title">${n.title}</div><div class="notif-desc">${n.text}</div><div class="notif-time">${n.time}</div></div>`;
    container.appendChild(div);
  });
}
function clearNotifications() { userState.notifications = []; renderUI(); showToast('Notifications cleared'); }
function pushNotification(title, text, type='blue') {
  userState.notifications.unshift({ id: Date.now(), title, text, time: 'Just now', type, unread: true });
  renderUI();
}

// ---------- Friend requests ----------
async function refreshIncomingRequests() {
  if (!userState.userId) return;
  try { userState.friendRequests = await api('/api/friend-requests/incoming'); renderUI(); }
  catch (e) { /* silent — server may just be starting up */ }
}
async function sendFriendRequestUI() {
  const input = document.getElementById('friendSocialIdInput');
  const targetId = input.value.trim().toUpperCase();
  if (!targetId) return;
  try { await api('/api/friend-request', { method: 'POST', body: { toSocialId: targetId } }); showToast(`Friend request sent to ${targetId}`); input.value = ''; }
  catch (e) { showToast(e.message); }
}
async function acceptFriendRequestUI(requestId) {
  try {
    await api(`/api/friend-request/${requestId}/accept`, { method: 'POST' });
    userState.friendRequests = userState.friendRequests.filter(r => r.id !== requestId);
    showToast('Friend added!'); renderUI(); loadCommFriendsUI();
  } catch (e) { showToast(e.message); }
}

// ---------- Profile edit ----------
function populateEditModal() {
  document.getElementById('editUsernameInput').value = userState.username;
  document.getElementById('editRoleSelect').value = userState.role || "Coder";
  document.getElementById('editBioInput').value = userState.bio || "";
  document.getElementById('editGithubInput').value = userState.github || "";
  document.getElementById('editTwitterInput').value = userState.twitter || "";
}
document.getElementById('editProfileForm').addEventListener('submit', async function(e) {
  e.preventDefault();
  const updates = {
    username: document.getElementById('editUsernameInput').value || userState.username,
    role: document.getElementById('editRoleSelect').value,
    bio: document.getElementById('editBioInput').value,
    github: document.getElementById('editGithubInput').value,
    twitter: document.getElementById('editTwitterInput').value
  };
  try { await api('/api/profile/me', { method: 'PUT', body: updates }); Object.assign(userState, updates); showToast('Profile saved'); }
  catch (e) { showToast(e.message); }
  closeModal('editProfileModal');
  renderUI();
});
async function incrementStat(type) {
  userState.stats[type] += 1;
  renderUI();
  try { await api('/api/profile/me', { method: 'PUT', body: { [type]: userState.stats[type] } }); showToast(`+1 ${type}, synced`); }
  catch (e) { showToast(`Could not sync +1 ${type}`); }
}
function extractDataSheet() {
  closeModal('profileModal');
  const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(userState, null, 2));
  const a = document.createElement('a');
  a.setAttribute("href", dataStr); a.setAttribute("download", `knight_datasheet_${userState.username}.json`);
  document.body.appendChild(a); a.click(); a.remove();
  showToast('Data Sheet exported & downloaded (.json)');
}
function copySocialId() { navigator.clipboard?.writeText(userState.socialId || '').then(() => showToast('Social ID copied')); }
function openDeviceSetup() { closeModal('profileModal'); openModal('deviceModal'); }
function signOutUI() {
  localStorage.removeItem('knight_token');
  location.reload();
}

