// ============================================================
// TERMINAL — real code execution via the public Piston API
// (unrelated to Supabase — always was a third-party runtime)
// ============================================================
const PISTON_VERSIONS = { javascript: '18.15.0', python: '3.10.0', 'c++': '10.2.0', c: '10.2.0', java: '15.0.2', typescript: '5.0.3', go: '1.16.2', rust: '1.68.2', php: '8.2.3', ruby: '3.0.1', bash: '5.2.0' };
const PISTON_EXT = { javascript: 'js', python: 'py', 'c++': 'cpp', c: 'c', java: 'java', typescript: 'ts', go: 'go', rust: 'rs', php: 'php', ruby: 'rb', bash: 'sh' };
function playErrorSound() {
  if (!document.getElementById('termAudioToggle')?.checked) return;
  try {
    const ctx = new (window.AudioContext || window.webkitAudioContext)();
    const osc = ctx.createOscillator(); const gain = ctx.createGain();
    osc.frequency.value = 220; osc.type = 'square';
    gain.gain.setValueAtTime(0.08, ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.3);
    osc.connect(gain); gain.connect(ctx.destination);
    osc.start(); osc.stop(ctx.currentTime + 0.3);
  } catch (e) {}
}
async function runCodeUI() {
  const lang = document.getElementById('termLanguage').value;
  const code = document.getElementById('termCodeInput').value;
  const out = document.getElementById('termOutput');
  const btn = document.getElementById('runCodeBtn');
  out.textContent = 'Running…'; btn.disabled = true;
  try {
    const res = await fetch('https://emkc.org/api/v2/piston/execute', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ language: lang, version: PISTON_VERSIONS[lang], files: [{ name: `main.${PISTON_EXT[lang]}`, content: code }] })
    });
    const data = await res.json();
    if (data.run) {
      const stdout = data.run.stdout || ''; const stderr = data.run.stderr || '';
      out.textContent = stdout + (stderr ? `\n--- stderr ---\n${stderr}` : '');
      if (stderr || data.run.code !== 0) playErrorSound();
    } else { out.textContent = 'Execution service returned no result: ' + JSON.stringify(data); playErrorSound(); }
  } catch (e) { out.textContent = 'Could not reach the code execution service: ' + e.message; playErrorSound(); }
  btn.disabled = false;
}

