  bubble.style.cssText = `align-self:${mine ? 'flex-end' : 'flex-start'}; background:${mine ? 'var(--accent-blue)' : 'rgba(255,255,255,.06)'}; color:${mine ? '#0b1420' : 'var(--text-primary)'}; padding:8px 14px; border-radius:14px; max-width:75%; font-size:.85rem;`;
